dtsPropsFor.ThemedText:
children?: React.ReactNode;
  /** 글자 크기와 굵기. 화면이 직접 fontSize를 정하지 않고 이 중에서 고른다. */
  type?: 'default' | 'title' | 'subtitle' | 'small' | 'smallBold' | 'link' | 'linkPrimary' | 'code';
  /** 어떤 색 역할을 쓸지. 밝은/어두운 모드는 useTheme이 알아서 고른다. */
  themeColor?: 'text' | 'textSecondary' | 'background' | 'backgroundElement' | 'backgroundSelected' | 'border' | 'tint' | 'tintInactive';
  style?: StyleProp<TextStyle>;
  numberOfLines?: number;
  accessibilityLabel?: string;
  accessibilityRole?: string;

dtsPropsFor.ThemedView:
children?: React.ReactNode;
  /** 배경으로 쓸 색 역할. 기본은 'background'. 카드는 'backgroundElement'를 쓴다. */
  type?: 'text' | 'textSecondary' | 'background' | 'backgroundElement' | 'backgroundSelected' | 'border' | 'tint' | 'tintInactive';
  style?: StyleProp<ViewStyle>;
  accessibilityLabel?: string;
  accessibilityRole?: string;

dtsPropsFor.ActionButton:
/** 단추에 적히는 말. 무엇이 일어날지 그대로 쓴다. */
  label: string;
  /** 라벨 아래 작은 글씨로 붙는 보조 설명. 왜 눌리지 않는지도 여기에 적는다. */
  hint?: string;
  /** 화면에서 가장 중요한 하나만 'primary'. 나머지는 기본값. */
  variant?: 'primary' | 'secondary';
  disabled?: boolean;
  onPress?: () => void;
  accessibilityLabel?: string;

dtsPropsFor.FilterChip:
/** 조건 이름. 개수를 붙일 때는 '서울 6곳'처럼 함께 적는다. */
  label: string;
  selected: boolean;
  onPress: () => void;
  /** 여럿 중 하나만 고르는 자리인지. 스크린 리더가 읽는 역할이 달라진다. */
  role?: 'checkbox' | 'radio';
